 32→      defaultTimeoutMs: config.defaultTimeoutMs ?? DEFAULT_HARNESS_TIMEOUT_MS
 33→    };
 34→    
 35→    this.spawner = new HarnessSpawner();
 36→    this.setupSpawnerListeners();
 37→  }
 38→
 39→  public static getInstance(): HarnessPool {
 40→    if (!HarnessPool.instance) {
 41→      HarnessPool.instance = new HarnessPool();
 42→    }
 43→    return HarnessPool.instance as HarnessPool;
 44→  }
 45→
 46→  private setupSpawnerListeners(): void {
 47→    // Forward events
 48→    this.spawner.on('status', (event) => {
 49→      this.emit('status', event);
 50→      
 51→      // If a slot opened up, process queue
 52→      if (['completed', 'failed', 'killed'].includes(event.status)) {
 53→        this.processQueue();
 54→      }
 55→    });
 56→
 57→    this.spawner.on('output', (event) => this.emit('output', event));
 58→  }
 59→
 60→/**
 61→   * Acquires a harness instance immediately or queues until capacity is available.
 62→   */
 63→  public async acquire(spawnConfig: Omit<SpawnConfig, 'timeoutMs'> & { timeoutMs?: number }): Promise<HarnessInstance> {
 64→    const config: SpawnConfig = {
 65→      ...spawnConfig,
 66→      timeoutMs: spawnConfig.timeoutMs ?? this.config.defaultTimeoutMs
 67→    };
 68→
 69→    // Check concurrency
 70→    const running = this.spawner.listRunning().length;
 71→    
 72→    if (running >= this.config.maxConcurrent) {
 73→      logger.info(`Pool full (${running}/${this.config.maxConcurrent}), queuing request...`);
 74→      return new Promise((resolve, reject) => {
 75→        this.queue.push({ config, resolve, reject });
 76→      });
 77→    }
 78→
 79→    return this.spawner.spawn(config);
 80→  }
 81→
 82→/**
 83→   * Dequeues and spawns the next waiting request when a slot is free.
 84→   */
 85→  private async processQueue(): Promise<void> {
 86→    const running = this.spawner.listRunning().length;
 87→    
 88→    if (running < this.config.maxConcurrent && this.queue.length > 0) {
 89→      const item = this.queue.shift();
 90→      if (item) {
 91→        logger.info('Processing queued harness request...');
 92→        try {
 93→          const instance = await this.spawner.spawn(item.config);
 94→          item.resolve(instance);
 95→        } catch (error) {
 96→          item.reject(error);
 97→          try { this.processQueue(); } catch { /* queue processing continues on next slot open */ }
 98→        }
 99→      }
100→    }
101→  }
102→
103→/**
104→   * Returns current pool metrics.
105→   */
106→  public getStats() {
107→    return {
108→      running: this.spawner.listRunning().length,
109→      queued: this.queue.length,
110→      maxConcurrent: this.config.maxConcurrent
111→    };
112→  }
113→
114→/**
115→   * Updates max concurrency and triggers queue processing.
116→   */
117→  public setMaxConcurrent(max: number): void {
118→    this.config.maxConcurrent = max;
119→    this.processQueue(); // We might have opened slots
120→  }
121→
122→/**
123→   * Kills running processes, rejects queued work, and clears listeners.
124→   */
125→  public shutdown(): void {
126→    this.spawner.shutdown();
127→    // Reject all queued items
128→    for (const item of this.queue) {
129→      item.reject(new Error('Pool shutting down'));
130→    }
131→    this.queue = [];
132→    this.removeAllListeners();
133→  }
134→
135→  // Delegate methods
136→  public kill(id: HarnessId) { return this.spawner.kill(id); }
137→  public sendInput(id: HarnessId, data: string) { return this.spawner.sendInput(id, data); }
138→  public waitFor(id: HarnessId) { return this.spawner.waitFor(id); }
139→  public getSpawner() { return this.spawner; }
140→}
141→
142→export const getHarnessPool = () => HarnessPool.getInstance();
